{
"title": "Bad Weather Over Longsaddle (v1.4)",
"language": "en",
"recommended_level": "1st-2nd-level party",
"hook": "Longrider. The character has heard that Longsaddle is a place where fortunes are made. Out on these frontier lands, ranchers, farmers, and wizards are always looking to hire folks who can fend off monsters, cattle thieves, and the occasional band of marauding barbarians.",
"npcs": [
    {
        "name": "Lee",
        "role": "Neutral Human rancher"
    },
    {
        "name": "Nuragha",
        "role": "Chaotic Good young copper dragon"
    }
],
"locations": [
    "Longsaddle hamlet",
    "Ranch lands northwest of Longsaddle",
    "Longhorn longhorns herds",
    "Dry ravine"
],
"threats": [
    "Copper dragon Ol’ Stinkybutt",
    "Cattle thieves (Jackalweres from the Gogan Brothers Gang)",
    "Wandering longhorns",
    "Parting shot from the copper dragon"
],
"rewards": [
    "Lee’s Reward: 20 gp",
    "Instrument of Illusions (Magic Item)",
    "Shield of Expression (Magic Item)"
]
}

